"""WO-062P (+ WO-088): the presenter sound effects, generated by numpy and committed."""

from __future__ import annotations

import importlib.util
import math
import subprocess
import sys
import wave
from pathlib import Path
from types import ModuleType

import numpy as np
import pytest

REPO = Path(__file__).resolve().parents[1]
SFX_DIR = REPO / "web" / "public" / "sfx"
GENERATOR = REPO / "scripts" / "gen_sfx.py"
NAMES = (
    "hail_ping",
    "advisory_chime",
    "hold_tone",
    "handoff_chime",
    "twist_klaxon_lite",
    # --- WO-088 begin ---
    "responder_dispatch",
    # --- WO-088 end ---
)


def _generator() -> ModuleType:
    spec = importlib.util.spec_from_file_location("gen_sfx", GENERATOR)
    assert spec is not None and spec.loader is not None
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


def _read(path: Path) -> tuple[int, np.ndarray]:
    with wave.open(str(path), "rb") as w:
        assert w.getnchannels() == 1 and w.getsampwidth() == 2
        rate = w.getframerate()
        frames = w.readframes(w.getnframes())
    return rate, np.frombuffer(frames, dtype="<i2")


def test_the_files_exist_and_nothing_else() -> None:
    assert sorted(p.name for p in SFX_DIR.glob("*.wav")) == sorted(f"{n}.wav" for n in NAMES)
    assert tuple(_generator().SOUNDS) == NAMES


@pytest.mark.parametrize("name", NAMES)
def test_under_one_second_at_minus_18_dbfs(name: str) -> None:
    rate, pcm = _read(SFX_DIR / f"{name}.wav")
    assert 0 < len(pcm) / rate < 1.0
    peak = int(np.max(np.abs(pcm.astype(np.int32))))
    peak_dbfs = 20.0 * math.log10(peak / 32767)
    assert abs(peak_dbfs - (-18.0)) <= 0.5, peak_dbfs
    assert (SFX_DIR / f"{name}.wav").stat().st_size < 64_000


@pytest.mark.parametrize("name", NAMES)
def test_no_click_at_either_end(name: str) -> None:
    _, pcm = _read(SFX_DIR / f"{name}.wav")
    peak = int(np.max(np.abs(pcm.astype(np.int32))))
    assert abs(int(pcm[0])) <= peak * 0.02 and abs(int(pcm[-1])) <= peak * 0.02


def test_generator_is_deterministic(tmp_path: Path) -> None:
    for run in ("a", "b"):
        subprocess.run(
            [sys.executable, str(GENERATOR), "--out", str(tmp_path / run)],
            check=True,
            capture_output=True,
        )
    for name in NAMES:
        a = (tmp_path / "a" / f"{name}.wav").read_bytes()
        b = (tmp_path / "b" / f"{name}.wav").read_bytes()
        assert a == b, name
        # The committed file is what the generator makes; allow 1 LSB for libm differences
        # between the machine that committed it and this one.
        rate_new, new = _read(tmp_path / "a" / f"{name}.wav")
        rate_old, old = _read(SFX_DIR / f"{name}.wav")
        assert rate_new == rate_old and len(new) == len(old), name
        assert int(np.max(np.abs(new.astype(np.int32) - old.astype(np.int32)))) <= 1, name


# --- WO-088 begin ---
def test_responder_dispatch_is_two_rising_notes() -> None:
    rate, pcm = _read(SFX_DIR / "responder_dispatch.wav")
    sig = pcm.astype(np.float64)
    assert len(sig) / rate < 0.5
    half = round(0.2 * rate)

    def pitch(part: np.ndarray) -> float:
        spec = np.abs(np.fft.rfft(part))
        return float(np.argmax(spec)) * rate / len(part)

    first, second = pitch(sig[:half]), pitch(sig[half:])
    assert abs(first - 659.25) < 15 and abs(second - 880.0) < 15
    assert second > first


# --- WO-088 end ---
